package ro.leo.visual;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.*;import android.provider.ContactsContract.CommonDataKinds.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Local fixtures only: no installer acceptance, uninstallation, audio, calls or real sharing. */
public final class PocketSuiteTests extends Instrumentation {
 int checks;void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 Field field(Object o,String n)throws Exception{Class<?> k=o.getClass();while(k!=null){try{Field f=k.getDeclaredField(n);f.setAccessible(true);return f;}catch(NoSuchFieldException e){k=k.getSuperclass();}}throw new NoSuchFieldException(n);}
 Object get(Object o,String n)throws Exception{return field(o,n).get(o);}void set(Object o,String n,Object v)throws Exception{field(o,n).set(o,v);}
 void call(final Object o,String name,Class<?>[] types,final Object...args)throws Exception{final Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();}
 Activity open(Class<?> k){return open(new Intent(getTargetContext(),k));}Activity open(Intent i){final Activity a=startActivitySync(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(new Runnable(){public void run(){a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);}});for(int n=0;n<40&&!a.hasWindowFocus();n++)SystemClock.sleep(100);return a;}
 void close(final Activity a){if(a!=null)runOnMainSync(new Runnable(){public void run(){a.finish();}});waitForIdleSync();}
 Activity home(){final Activity[] out={null};runOnMainSync(new Runnable(){public void run(){getTargetContext().startActivity(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}});for(int i=0;i<50&&out[0]==null;i++){runOnMainSync(new Runnable(){public void run(){try{Class<?> t=Class.forName("android.app.ActivityThread");Object thread=t.getMethod("currentActivityThread").invoke(null);Field f=t.getDeclaredField("mActivities");f.setAccessible(true);for(Object record:((Map<?,?>)f.get(thread)).values()){Field a=record.getClass().getDeclaredField("activity");a.setAccessible(true);Object page=a.get(record);if(page instanceof MainActivity&&!((Activity)page).isDestroyed())out[0]=(Activity)page;}}catch(Exception e){throw new RuntimeException(e);}}});if(out[0]==null)SystemClock.sleep(100);}if(out[0]==null)throw new AssertionError("Home unavailable");for(int i=0;i<30&&!out[0].hasWindowFocus();i++)SystemClock.sleep(100);return out[0];}
 void capture(String name)throws Exception{waitForIdleSync();SystemClock.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(getTargetContext().getFilesDir(),"flow-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 void restore(Context c,Map<String,?> values){SharedPreferences.Editor e=c.getSharedPreferences("appearance",0).edit().clear();for(Map.Entry<String,?> pair:values.entrySet()){Object v=pair.getValue();if(v instanceof String)e.putString(pair.getKey(),(String)v);else if(v instanceof Integer)e.putInt(pair.getKey(),(Integer)v);else if(v instanceof Boolean)e.putBoolean(pair.getKey(),(Boolean)v);}e.commit();}
 void restorePrefs(SharedPreferences p,Map<String,?> old){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> pair:old.entrySet()){Object v=pair.getValue();String k=pair.getKey();if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Set)e.putStringSet(k,new HashSet<String>((Set<String>)v));}e.commit();}
 public void onCreate(Bundle b){start();}
 public void onStart(){Context c=getTargetContext();Bundle out=new Bundle();Activity a=null;File dir=new File(c.getExternalFilesDir(null),"pocket-"+UUID.randomUUID());SharedPreferences reader=c.getSharedPreferences("reader",0),game=c.getSharedPreferences("GamesActivity",0),appearance=c.getSharedPreferences("appearance",0);Map<String,?> oldReader=new HashMap<String,Object>(reader.getAll()),oldGame=new HashMap<String,Object>(game.getAll()),oldAppearance=new HashMap<String,Object>(appearance.getAll());File checkpoint=ThemeCheckpoint.file(c);byte[] oldCheckpoint=null;try{
  if(BackupEngine.atomicExists(checkpoint))oldCheckpoint=BackupEngine.atomicBytes(checkpoint,3145728);dir.mkdirs();File book=new File(dir,"Leo fixture.txt");BackupEngine.write(book,"Lectură Leo.\nȘtiință și text local, fără conexiune.".getBytes("UTF-8"));
  File epub=new File(dir,"Leo fixture.epub");java.util.LinkedHashMap<String,String> xml=new java.util.LinkedHashMap<String,String>();xml.put("mimetype","application/epub+zip");xml.put("META-INF/container.xml","<container><rootfiles><rootfile full-path='content.opf'/></rootfiles></container>");xml.put("content.opf","<package><metadata><title>Carte locală</title></metadata><manifest><item id='one' href='one.xhtml' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='one'/></spine></package>");xml.put("one.xhtml","<!DOCTYPE html><html><head><title>Capitol</title></head><body><p>Știință EPUB.</p></body></html>");try(java.util.zip.ZipOutputStream outZip=new java.util.zip.ZipOutputStream(new FileOutputStream(epub))){for(Map.Entry<String,String> e:xml.entrySet()){outZip.putNextEntry(new java.util.zip.ZipEntry(e.getKey()));outZip.write(e.getValue().getBytes("UTF-8"));outZip.closeEntry();}}check(BookDocument.read(epub).chapters.get(0).contains("Știință EPUB"),"EPUB parsed by the Android XML providers without network");
  check(AppCatalog.NAMES.length==35&&IconArt.COLORS.length==35,"six new stable catalog IDs have artwork");check("Ajutor Leo".equals(AppCatalog.NAMES[28])&&"Cărți Leo".equals(AppCatalog.NAMES[30]),"old app IDs retained");
  a=open(new Intent(c,ReaderActivity.class).putExtra("file",book.getPath()));for(int i=0;i<50&&get(a,"book")==null;i++)SystemClock.sleep(100);check(get(a,"book")!=null&&((TextView)get(a,"body")).getText().toString().contains("Știință"),"reader renders UTF-8 fixture on Android");call(a,"bookmark",new Class<?>[]{});call(a,"bookmark",new Class<?>[]{});String id=(String)get(a,"key");check(new JSONArray(reader.getString(id+"-marks","[]")).length()==1,"duplicate bookmarks do not consume slots");call(a,"onKeyDown",new Class<?>[]{int.class,KeyEvent.class},KeyEvent.KEYCODE_POUND,new KeyEvent(0,KeyEvent.KEYCODE_POUND));check(((Integer)get(a,"font"))==19,"reader keypad font control");close(a);a=null;
  a=open(GamesActivity.class);check(((List)get(a,"listRows")).size()==3,"three keypad games exposed");set(a,"game",1);call(a,"newGame",new Class<?>[]{boolean.class},true);call(a,"show",new Class<?>[]{});call(a,"onKeyDown",new Class<?>[]{int.class,KeyEvent.class},KeyEvent.KEYCODE_DPAD_RIGHT,new KeyEvent(0,KeyEvent.KEYCODE_DPAD_RIGHT));check(((Integer)get(a,"selected"))==1,"Sudoku focus moves physically");close(a);a=null;
  ThemeCheckpoint.apply(c,0,false);check(appearance.getInt("theme",-1)==10,"theme manager applies full application palette");ThemeCheckpoint.restore(c);check(appearance.getInt("theme",0)==(oldAppearance.get("theme") instanceof Integer?(Integer)oldAppearance.get("theme"):0),"visual checkpoint restores prior palette");a=open(ThemePacksActivity.class);set(a,"selected",0);call(a,"preview",new Class<?>[]{});call(a,"onKeyDown",new Class<?>[]{int.class,KeyEvent.class},22,new KeyEvent(0,22));check(((Integer)get(a,"tab"))==1,"theme preview changes tabs from D-pad");close(a);a=null;
  a=open(UpdatesActivity.class);check(((List)get(a,"listRows")).size()==8,"update actions are explicit");close(a);a=null;check(!UpdateEngine.prefs(c).getBoolean("active",false),"test does not open an installation session");PackageInfo own=c.getPackageManager().getPackageInfo(c.getPackageName(),PackageManager.GET_SIGNATURES);check(UpdateEngine.validate(c,new File(own.applicationInfo.sourceDir),1).packageName.equals(c.getPackageName()),"archive metadata matches installed signature");boolean rejected=false;try{UpdateEngine.validate(c,new File(own.applicationInfo.sourceDir),0);}catch(Exception expected){rejected=true;}check(rejected,"wrong package rejected even with same signing key");
  a=open(CameraActivity.class);check(((List)get(a,"listRows")).toString().contains("Camere raportate"),"camera status visible without opening hardware");check(get(a,"camera")==null,"camera never opened by diagnostic screen");close(a);a=null;
  a=open(ConnectionDashboardActivity.class);for(int i=0;i<50&&get(a,"listRows")==null;i++)SystemClock.sleep(100);check(((List)get(a,"listRows")).toString().contains("USB"),"connection overview shows USB state without toggling");close(a);a=null;
  out.putString("result","PASS "+checks+" pocket-suite checks; local fixtures, no camera open, network changes, audio or install session");
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finally{close(a);try{restorePrefs(reader,oldReader);restorePrefs(game,oldGame);restorePrefs(appearance,oldAppearance);if(oldCheckpoint==null)new android.util.AtomicFile(checkpoint).delete();else BackupEngine.write(checkpoint,oldCheckpoint);File[] files=dir.listFiles();if(files!=null)for(File f:files)f.delete();dir.delete();}catch(Exception e){out.putString("cleanup_error",e.toString());}}finish(out.containsKey("error")||out.containsKey("cleanup_error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
